SELECT w.wanted_id AS wantedId, w.user_id AS userId, u.username AS username, w.title AS title, w.category_id AS categoryId, w.budget_min AS budgetMin, w.budget_max AS budgetMax, w.campus AS campus, w.description AS description, w.status AS status, w.response_count AS responseCount, w.create_time AS createTime, w.update_time AS updateTime FROM wanted_post w LEFT JOIN `user` u ON w.user_id = u.user_id
AND w.title LIKE CONCAT('%', #{keyword}, '%')
AND w.category_id = #{categoryId}
AND w.campus = #{campus}
AND w.budget_max <= #{budgetMax}
AND w.status = #{status}
ORDER BY w.budget_max DESC, w.wanted_id DESC
ORDER BY w.budget_max ASC, w.wanted_id DESC
ORDER BY w.create_time DESC, w.wanted_id DESC
LIMIT #{offset}, #{pageSize}

